steps.script:
await $type('#page .m-pagination-group input[type="text"]', String(__input__.page));
await $click('#page .m-pagination-group button[type="button"]');
await new Promise(r => setTimeout(r, 3000));
return { done: true };

const items = await $list('ul.wb-data-item li.wb-data-list a.ewb-data-txt');
if (!items || items.length === 0) {
  return { done: false };
}
const links = items.map(el => ({
  href: el.href,
  text: (el.textContent || '').trim()
}));
return { items: links, index: 0, results: [] };

const state = __lastResult__;
if (!state || !state.items || state.index >= state.items.length) {
  return { done: true, results: state ? state.results : [] };
}
const item = state.items[state.index];
const detail = await $openTab(item.href, `
  await $wait('h3.ewb-notice-tt', 10000);
  await new Promise(r => setTimeout(r, 2000));
  let title = '';
  try { title = await $extract('h3.ewb-notice-tt', null, 5000); } catch(e) {}
  let zhaobiao = '';
  try { zhaobiao = await $extract('iframe#zbggframe1::div.ewb-info-main', null, 8000); } catch(e) {}
  let chengqing = '';
  try { chengqing = await $extract('iframe#bgggframe1::div.ewb-info-main', null, 5000); } catch(e) {}
  let houxaun = '';
  try { houxaun = await $extract('iframe#hxgsframe1::div.ewb-info-main', null, 5000); } catch(e) {}
  let zhongbiao = '';
  try { zhongbiao = await $extract('iframe#zbgsframe1::div.ewb-info-main', null, 5000); } catch(e) {}
  return { title: title || '', zhaobiao: zhaobiao || '', chengqing: chengqing || '', houxaun: houxaun || '', zhongbiao: zhongbiao || '' };
`);
const result = {
  title: detail.title || item.text || '',
  url: item.href,
  招标公告: detail.zhaobiao || '',
  '澄清/变更公告': detail.chengqing || '',
  '中标候选人公示': detail.houxaun || '',
  '中标公示': detail.zhongbiao || ''
};
state.results.push(result);
state.index++;
return { done: false, items: state.items, index: state.index, results: state.results };
